import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';

/**
 * Sidebar groups built from the docs folder on disk.
 *
 * Why not Starlight's `autogenerate`: it picks a group's pages by stripping `src/content/docs/`
 * from each entry's filePath. Ours load from `../../docs/` (see content.config.ts), so nothing
 * is stripped, nothing matches, and every autogenerated group rendered as an empty list.
 *
 * Same rules as autogenerate: `sidebar.order` first, then alphabetical; `sidebar.hidden` skipped;
 * README/index leads its folder; a folder with more than its index becomes a collapsed subgroup.
 */
/** Same normalisation as the glob loader's generateId. */
const toSlug = (rel) => rel.replace(/\.mdx?$/, '').toLowerCase().replace(/(^|\/)readme$/, '$1index');

/**
 * A real YAML parse, not regexes: scripts/generate.mjs writes `sidebar: {"hidden":true}` in flow
 * style while hand-written pages use block style, and a regex that read only one form leaked the
 * hidden skill reference pages into the sidebar.
 */
function frontmatter(file) {
  const m = /^---\n([\s\S]*?)\n---/.exec(readFileSync(file, 'utf8').replace(/\r\n/g, '\n'));
  const fm = (m && yaml.load(m[1])) || {};
  const sb = fm.sidebar ?? {};
  return {
    order: typeof sb.order === 'number' ? sb.order : Infinity,
    hidden: sb.hidden === true,
    title: typeof sb.label === 'string' ? sb.label : fm.title,
  };
}

const isIndex = (name) => /^(readme|index)\.mdx?$/i.test(name);

/** @returns {any[]} Starlight sidebar items for `dir` (relative to the docs root). */
export function dirItems(docsRoot, dir) {
  const abs = path.join(docsRoot, dir);
  if (!existsSync(abs)) return [];

  const entries = [];
  for (const e of readdirSync(abs, { withFileTypes: true })) {
    const rel = `${dir}/${e.name}`;
    if (e.isDirectory()) {
      const children = dirItems(docsRoot, rel);
      if (children.length === 0) continue;
      const index = readdirSync(path.join(docsRoot, rel)).find(isIndex);
      const fm = index ? frontmatter(path.join(docsRoot, rel, index)) : { order: Infinity };
      const item =
        children.length === 1
          ? children[0]
          : { label: fm.title ?? e.name, collapsed: true, items: children };
      entries.push({ item, order: fm.order, key: e.name, index: false });
    } else if (/^[^_].*\.mdx?$/.test(e.name)) {
      const fm = frontmatter(path.join(abs, e.name));
      if (fm.hidden) continue;
      entries.push({ item: { slug: toSlug(rel) }, order: fm.order, key: e.name, index: isIndex(e.name) });
    }
  }

  return entries
    .sort((a, b) => Number(b.index) - Number(a.index) || a.order - b.order || a.key.localeCompare(b.key))
    .map((e) => e.item);
}
